<script setup lang="ts">import { onMounted,onUnmounted,ref } from 'vue';import UiIcon from './UiIcon.vue';defineProps<{title:string}>();const emit=defineEmits<{close:[]}>();const panel=ref<HTMLElement>();const key=(event:KeyboardEvent)=>{if(event.key==='Escape')emit('close')};onMounted(()=>{document.addEventListener('keydown',key);panel.value?.focus()});onUnmounted(()=>document.removeEventListener('keydown',key))</script>
<template><div class="modal-backdrop" role="presentation" @mousedown.self="emit('close')"><section ref="panel" class="modal card" role="dialog" aria-modal="true" :aria-label="title" tabindex="-1"><header><h2>{{title}}</h2><button class="icon-button" type="button" aria-label="Zamknij" @click="emit('close')"><UiIcon name="X"/></button></header><slot/></section></div></template>
